    34  h2o_http2_stream_t *h2o_http2_stream_open(h2o_http2_conn_t *conn, uint32_t stream_id, h2o_req_t *src_req,
    35                                            const h2o_http2_priority_t *received_priority)
    36  {
    37      h2o_http2_stream_t *stream = h2o_mem_alloc(sizeof(*stream));
    38
    39      /* init properties (other than req) */
    40      memset(stream, 0, offsetof(h2o_http2_stream_t, req));
    41      stream->stream_id = stream_id;
    42      stream->_ostr_final.do_send = finalostream_send;
    43      stream->_ostr_final.start_pull = finalostream_start_pull;
    44      stream->state = H2O_HTTP2_STREAM_STATE_IDLE;
    45      h2o_http2_window_init(&stream->output_window, &conn->peer_settings);
    46      h2o_http2_window_init(&stream->input_window, &H2O_HTTP2_SETTINGS_HOST);
    47      stream->received_priority = *received_priority;
    48
    49      /* init request */
    50      h2o_init_request(&stream->req, &conn->super, src_req);
    51      stream->req.version = 0x200;
    52      if (src_req != NULL)
    53          memset(&stream->req.upgrade, 0, sizeof(stream->req.upgrade));
    54      stream->req._ostr_top = &stream->_ostr_final;
    55
    56      h2o_http2_conn_register_stream(conn, stream);
    57
    58      ++conn->num_streams.priority.open;
    59      stream->_num_streams_slot = &conn->num_streams.priority;
    60
    61      return stream;
    62  }
    63
    64  void h2o_http2_stream_close(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
    65  {
    66      h2o_http2_conn_unregister_stream(conn, stream);
    67      if (stream->_req_body.body != NULL)
    68          h2o_buffer_dispose(&stream->_req_body.body);
    69      if (stream->cache_digests != NULL)
    70          h2o_cache_digests_destroy(stream->cache_digests);
    71      h2o_dispose_request(&stream->req);
    72      if (stream->stream_id == 1 && conn->_http1_req_input != NULL)
    73          h2o_buffer_dispose(&conn->_http1_req_input);
    74      free(stream);
    75  }
    76
    77  void h2o_http2_stream_reset(h2o_http2_conn_t *conn, h2o_http2_stream_t *stream)
    78  {
    79      switch (stream->state) {
    80      case H2O_HTTP2_STREAM_STATE_IDLE:
    81      case H2O_HTTP2_STREAM_STATE_RECV_HEADERS:
    82      case H2O_HTTP2_STREAM_STATE_RECV_BODY:
    83      case H2O_HTTP2_STREAM_STATE_REQ_PENDING:
    84          h2o_http2_stream_close(conn, stream);
    85          break;
    86      case H2O_HTTP2_STREAM_STATE_SEND_HEADERS:
    87      case H2O_HTTP2_STREAM_STATE_SEND_BODY:
    88      case H2O_HTTP2_STREAM_STATE_SEND_BODY_IS_FINAL:
    89          h2o_http2_stream_set_state(conn, stream, H2O_HTTP2_STREAM_STATE_END_STREAM);
    90      /* continues */
    91      case H2O_HTTP2_STREAM_STATE_END_STREAM:
    92          /* clear all the queued bufs, and close the connection in the callback */
    93          stream->_data.size = 0;
    94          if (h2o_linklist_is_linked(&stream->_refs.link)) {
    95              /* will be closed in the callback */
    96          } else {
    97              h2o_http2_stream_close(conn, stream);
    98          }
    99          break;
   100      }
